// conv_transpose3d_fastpath:
//   - Expands input via zero-insertion into a buffer pre-padded for
//     a stride-1 forward conv3d with 'same' weight (no extra padding needed).
//   - Calls at::conv3d with stride=1, padding=0 (padding already baked in).
//   - Adds bias if present.
// For ConvTranspose3d: weight layout is [Cin, Cout, kD, kH, kW].
// Forward conv3d expects [Cout, Cin, kD, kH, kW], so we permute.
// ---------------------------------------------------------------------------
torch::Tensor conv_transpose3d_fastpath(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias,
    int pad_d, int pad_h, int pad_w,
    int outpad_d, int outpad_h, int outpad_w
) {
    TORCH_CHECK(input.is_cuda() && input.dtype() == torch::kFloat32 && input.is_contiguous());
    TORCH_CHECK(weight.is_cuda() && weight.dtype() == torch::kFloat32 && weight.is_contiguous());

    const int stride = 2;

    int N   = input.size(0);
    int Cin = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);

    // weight: [Cin, Cout, kD, kH, kW]
    int kD = weight.size(2);
    int kH = weight.size(3);
    int kW = weight.size(4);

    // Output spatial dims for transposed conv:
    //   out = (in - 1)*stride - 2*pad + k + outpad
    int D_out_target = (D_in - 1) * stride - 2 * pad_d + kD + outpad_d;
    int H_out_target = (H_in - 1) * stride - 2 * pad_h + kH + outpad_h;
    int W_out_target = (W_in - 1) * stride - 2 * pad_w + kW + outpad_w;

    // Expanded buffer: place input at stride-spaced positions, surrounded by
    // (kD-1-pad_d) zeros on each side so that a stride-1 conv with no extra
    // padding produces the correct output size.
    int pad_d_pre = kD - 1 - pad_d;
    int pad_h_pre = kH - 1 - pad_h;
    int pad_w_pre = kW - 1 - pad_w;

    // D_exp = (D_in-1)*stride+1 + 2*pad_d_pre
    // A stride-1 conv on this with kernel kD produces:
    //   D_exp - kD + 1 = (D_in-1)*stride+1 + 2*(kD-1-pad_d) - kD + 1
    //                  = (D_in-1)*stride - 2*pad_d + kD  (matches D_out_target when outpad=0)
    int D_exp_base = (D_in - 1) * stride + 1 + 2 * pad_d_pre;
    int H_exp_base = (H_in - 1) * stride + 1 + 2 * pad_h_pre;
    int W_exp_base = (W_in - 1) * stride + 1 + 2 * pad_w_pre;

    // Handle output_padding: append outpad rows/cols/slices after conv
    // We add outpad to the expanded buffer's trailing dimension.
    int D_exp = D_exp_base + outpad_d;
    int H_exp = H_exp_base + outpad_h;
    int W_exp = W_exp_base + outpad_w;

    auto expanded = torch::zeros({N, Cin, D_exp, H_exp, W_exp}, input.options());

    int total_in = N * Cin * D_in * H_in * W_in;
    int threads = 256;
    int blocks  = (total_in + threads - 1) / threads;
    zero_insert_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        expanded.data_ptr<float>(),
        N, Cin, D_in, H_in, W_in,
        D_exp, H_exp, W_exp,
        stride,
        pad_d_pre, pad_h_pre, pad_w_pre
    );

    // Permute weight [Cin, Cout, kD, kH, kW] -> [Cout, Cin, kD, kH, kW]
    auto weight_fwd = weight.permute({1, 0, 2, 3, 4}).contiguous();

    // Forward conv3d with stride=1, padding=0
    auto result = at::conv3d(expanded, weight_fwd, torch::Tensor(),
                             /*stride=*/{1,1,1}, /*padding=*/{0,0,0});

    // Trim to target size in case D_exp produced slightly more than needed
    if (result.size(2) != D_out_target || result.size(3) != H_out_target || result.size(4) != W_out_target) {
        result = result.slice(2, 0, D_out_target).slice(3, 0, H_out_target).slice(4, 0, W_out_target).contiguous();
    }

    if (bias.has_value() && bias.value().defined()) {
        auto b = bias.value().contiguous();
        result = result + b.view({1, -1, 1, 1, 1});
    }

    return result;
}
