//   D_exp = D_in*stride - stride + 1 + 2*(kD-1-pad)  (i.e. pre-padded for conv)
// We insert the input value at the strided position inside the
// "padded expanded" space: offset = (kD-1-pad_d) added on each side.
// ---------------------------------------------------------------------------
__global__ void zero_insert_kernel(
    const float* __restrict__ inp,
    float* __restrict__ expanded,
    int N, int Cin,
    int D_in, int H_in, int W_in,
    int D_exp, int H_exp, int W_exp,
    int stride,
    int pad_d_pre, int pad_h_pre, int pad_w_pre
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * Cin * D_in * H_in * W_in;
    if (idx >= total) return;

    int w = idx % W_in; int tmp = idx / W_in;
    int h = tmp % H_in; tmp /= H_in;
    int d = tmp % D_in; tmp /= D_in;
    int c = tmp % Cin;
    int n = tmp / Cin;

    int ed = d * stride + pad_d_pre;
    int eh = h * stride + pad_h_pre;
    int ew = w * stride + pad_w_pre;

    int out_idx = ((n * Cin + c) * D_exp + ed) * H_exp * W_exp + eh * W_exp + ew;
    expanded[out_idx] = inp[idx];
}

// ---------------------------------------------------------------------------
