    const float* __restrict__ multiplier,
    float* __restrict__ output,
    int N, int C, int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out
) {
    int nc = blockIdx.y;
    int c = nc % C;
    int n = nc / C;

    __shared__ float smem_mult;
    if (threadIdx.x == 0) {
        smem_mult = multiplier[c];
    }
    __syncthreads();

    float mult = smem_mult;

    int spatial_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int spatial_total = D_out * H_out * W_out;
    if (spatial_idx >= spatial_total) return;

    int w_out = spatial_idx % W_out;
    int tmp   = spatial_idx / W_out;
    int h_out = tmp % H_out;
    int d_out = tmp / H_out;

    int d_base = d_out * 2;
    int h_base = h_out * 2;
    int w_base = w_out * 2;

    int nc_stride = D_in * H_in * W_in;
    int nc_offset = (n * C + c) * nc_stride;

    float max_val = -1e38f;

    for (int kd = 0; kd < 2; kd++) {
        int d = d_base + kd;
        if (d >= D_in) continue;
        for (int kh = 0; kh < 2; kh++) {
            int h = h_base + kh;
            if (h >= H_in) continue;
            for (int kw = 0; kw < 2; kw++) {
                int w = w_base + kw;
                if (w >= W_in) continue;

                int in_idx = nc_offset + d * H_in * W_in + h * W_in + w;
                float v = conv_out[in_idx];

                v = fmaxf(v, 0.2f * v);
                v = v * mult;
                v = fmaxf(v, 0.2f * v);

                max_val = fmaxf(max_val, v);
            }
        }
    }

    int out_idx = (nc * D_out + d_out) * H_out * W_out + h_out * W_out + w_out;
    output[out_idx] = max_val;
}

torch::Tensor fused_act_pool(torch::Tensor conv_out, torch::Tensor multiplier) {
    TORCH_CHECK(conv_out.is_cuda(), "conv_out must be a CUDA tensor");
    TORCH_CHECK(multiplier.is_cuda(), "multiplier must be a CUDA tensor");
    TORCH_CHECK(conv_out.dtype() == torch::kFloat32, "conv_out must be float32");
    TORCH_CHECK(multiplier.dtype() == torch::kFloat32, "multiplier must be float32");
    TORCH_CHECK(conv_out.dim() == 5, "conv_out must be 5D (NCDHW)");
    TORCH_CHECK(conv_out.is_contiguous(), "conv_out must be contiguous");
    TORCH_CHECK(multiplier.is_contiguous(), "multiplier must be contiguous");

    int N    = conv_out.size(0);
    int C    = conv_out.size(1);
    int D_in = conv_out.size(2);
    int H_in = conv_out.size(3);
    int W_in = conv_out.size(4);

    TORCH_CHECK(multiplier.size(0) == C, "multiplier first dimension must match channels");

    int D_out = D_in / 2;
    int H_out = H_in / 2;
    int W_out = W_in / 2;

    auto output = torch::empty({N, C, D_out, H_out, W_out}, conv_out.options());

    int spatial_total = D_out * H_out * W_out;
    int threads  = 128;
    int blocks_x = (spatial_total + threads - 1) / threads;
    int blocks_y = N * C;

    dim3 grid(blocks_x, blocks_y);
    dim3 block(threads);

    fused_act_pool_kernel<<<grid, block>>>(
        conv_out.data_ptr<float>(),
        multiplier.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, D_in, H_in, W_in,
        D_out, H_out, W_out
    );

    return output;
}

// ---------------------------------------------------------------------------
// Zero-insertion kernel for stride-2 transposed conv fast path
// Each thread places one input element into the expanded buffer.
// Expanded buffer has shape (N, Cin, D_exp, H_exp, W_exp) where
//   D_exp = D_in*stride - stride + 1 + 2*(kD-1-pad)  (i.e. pre-padded for conv)
// We insert the input value at the strided position inside the
// "padded expanded" space: offset = (kD-1-pad_d) added on each side.
// ---------------------------------------------------------------------------
__global__ void zero_insert_kernel(
    const float* __restrict__ inp,
    float* __restrict__ expanded,
    int N, int Cin,
    int D_in, int H_in, int W_in,
    int D_exp, int H_exp, int W_exp,
    int stride,
    int pad_d_pre, int pad_h_pre, int pad_w_pre
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * Cin * D_in * H_in * W_in;
    if (idx >= total) return;

    int w = idx % W_in; int tmp = idx / W_in;
    int h = tmp % H_in; tmp /= H_in;
    int d = tmp % D_in; tmp /= D_in;
    int c = tmp % Cin;
    int n = tmp / Cin;

    int ed = d * stride + pad_d_pre;
    int eh = h * stride + pad_h_pre;
    int ew = w * stride + pad_w_pre;

    int out_idx = ((n * Cin + c) * D_exp + ed) * H_exp * W_exp + eh * W_exp + ew;
    expanded[out_idx] = inp[idx];
}

// ---------------------------------------------------------------------------
// conv_transpose3d_fastpath:
//   - Expands input via zero-insertion into a buffer pre-padded for
//     a stride-1 forward conv3d with 'same' weight (no extra padding needed).
//   - Calls at::conv3d with stride=1, padding=0 (padding already baked in).
//   - Adds bias if present.
// For ConvTranspose3d: weight layout is [Cin, Cout, kD, kH, kW].
// Forward conv3d expects [Cout, Cin, kD, kH, kW], so we permute.
// ---------------------------------------------------------------------------
torch::Tensor conv_transpose3d_fastpath(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias,
    int pad_d, int pad_h, int pad_w,
    int outpad_d, int outpad_h, int outpad_w
) {
    TORCH_CHECK(input.is_cuda() && input.dtype() == torch::kFloat32 && input.is_contiguous());
    TORCH_CHECK(weight.is_cuda() && weight.dtype() == torch::kFloat32 && weight.is_contiguous());

    const int stride = 2;

    int N   = input.size(0);
    int Cin = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);

    // weight: [Cin, Cout, kD, kH, kW]
    int kD = weight.size(2);
    int kH = weight.size(3);
    int kW = weight.size(4);

    // Output spatial dims for transposed conv:
    //   out = (in - 1)*stride - 2*pad + k + outpad
    int D_out_target = (D_in - 1) * stride - 2 * pad_d + kD + outpad_d;
    int H_out_target = (H_in - 1) * stride - 2 * pad_h + kH + outpad_h;
    int W_out_target = (W_in - 1) * stride - 2 * pad_w + kW + outpad_w;

    // Expanded buffer: place input at stride-spaced positions, surrounded by
    // (kD-1-pad_d) zeros on each side so that a stride-1 conv with no extra
    // padding produces the correct output size.
    int pad_d_pre = kD - 1 - pad_d;
    int pad_h_pre = kH - 1 - pad_h;
    int pad_w_pre = kW - 1 - pad_w;

    // D_exp = (D_in-1)*stride+1 + 2*pad_d_pre
    // A stride-1 conv on this with kernel kD produces:
    //   D_exp - kD + 1 = (D_in-1)*stride+1 + 2*(kD-1-pad_d) - kD + 1
    //                  = (D_in-1)*stride - 2*pad_d + kD  (matches D_out_target when outpad=0)
    int D_exp_base = (D_in - 1) * stride + 1 + 2 * pad_d_pre;
    int H_exp_base = (H_in - 1) * stride + 1 + 2 * pad_h_pre;
    int W_exp_base = (W_in - 1) * stride + 1 + 2 * pad_w_pre;

    // Handle output_padding: append outpad rows/cols/slices after conv
    // We add outpad to the expanded buffer's trailing dimension.
    int D_exp = D_exp_base + outpad_d;
    int H_exp = H_exp_base + outpad_h;
    int W_exp = W_exp_base + outpad_w;

    auto expanded = torch::zeros({N, Cin, D_exp, H_exp, W_exp}, input.options());

    int total_in = N * Cin * D_in * H_in * W_in;
    int threads = 256;
    int blocks  = (total_in + threads - 1) / threads;
    zero_insert_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        expanded.data_ptr<float>(),
        N, Cin, D_in, H_in, W_in,
        D_exp, H_exp, W_exp,
        stride,
        pad_d_pre, pad_h_pre, pad_w_pre
    );

    // Permute weight [Cin, Cout, kD, kH, kW] -> [Cout, Cin, kD, kH, kW]
    auto weight_fwd = weight.permute({1, 0, 2, 3, 4}).contiguous();

    // Forward conv3d with stride=1, padding=0
    auto result = at::conv3d(expanded, weight_fwd, torch::Tensor(),
                             /*stride=*/{1,1,1}, /*padding=*/{0,0,0});

    // Trim to target size in case D_exp produced slightly more than needed
    if (result.size(2) != D_out_target || result.size(3) != H_out_target || result.size(4) != W_out_target) {
        result = result.slice(2, 0, D_out_target).slice(3, 0, H_out_target).slice(4, 0, W_out_target).contiguous();
    }

    if (bias.has_value() && bias.value().defined()) {
        auto b = bias.value().contiguous();
        result = result + b.view({1, -1, 1, 1, 1});
    }

    return result;
}
